gather:
  execution_type: system_node
  subscribes_to: [batch.opened, item.reported]
  event_handlers:
    batch.opened:
      data_accumulation:
        writes:
          - {source_field: batch_id, target_field: batch_id}
          - {source_field: expected_item_ids, target_field: expected_item_ids}
      advances_to: awaiting
    item.reported:
      join:
        stage: awaiting
        members: {from: state.expected_item_ids, by: payload.item_id}
        output: payload.value
        on_complete: {advances_to: complete}
        deadline: {after: 5m, from: stage_entry}
        on_deadline: {advances_to: failed}

hub-node:
  execution_type: system_node
  subscribes_to: [hub.start, hub.bump, hub.close, hub.again]
  event_handlers:
    hub.start:
      data_accumulation:
        writes:
          - {source_field: hub_id, target_field: hub_id}
          - {target_field: count, value: 0}
      advances_to: active
      emit: {event: hub.work, fields: {hub_id: payload.hub_id, wave: 1}}
    hub.again:
      emit: {event: hub.work, fields: {hub_id: payload.hub_id, wave: payload.wave}}
    hub.bump:
      data_accumulation:
        writes:
          - {target_field: count, value: entity.count + 1}
    hub.close: {advances_to: closed}

hub-node:
  execution_type: system_node
  subscribes_to: [hub.start, hub.begin, hub.close]
  event_handlers:
    hub.start:
      data_accumulation:
        writes:
          - {source_field: hub_id, target_field: hub_id}
          - {target_field: items, value: []}
          - {target_field: labels, value: {}}
          - {target_field: positions, value: ["initial-0", "initial-1"]}
          - {target_field: marker, value: "initial"}
          - {target_field: results, value: 0}
    hub.begin:
      advances_to: working
      emit: {event: hub.work, fields: {hub_id: payload.hub_id}}
    hub.close: {advances_to: closed}

hub-node:
  execution_type: system_node
  subscribes_to: [hub.start, hub.begin, hub.close, hub.result]
  event_handlers:
    hub.start:
      data_accumulation:
        writes:
          - {source_field: hub_id, target_field: hub_id}
          - {target_field: items, value: []}
          - {target_field: labels, value: {}}
          - {target_field: positions, value: ["initial-0", "initial-1"]}
          - {target_field: marker, value: "initial"}
          - {target_field: results, value: 0}
    hub.begin:
      advances_to: working
      emit: {event: hub.work, fields: {hub_id: payload.hub_id}}
    hub.close: {advances_to: closed}
    hub.result:
      guard: {id: retained_in_new_stage, check: _entity.current_state == 'review'}
      data_accumulation:
        writes:
          - {target_field: result, value: payload.value}
          - {target_field: result_stage, value: _entity.current_state}
          - target_field: results
            value: |-
              has(entity.results) ? entity.results + 1 : 1
